async def act(page):
    """
    Update order #000000299 shipping address to:
      456 Oak Avenue
      Apartment 5B
      New York, NY 10001

    Operates from the current page state (document "Magento Admin"). Uses
    accessibility-centric selectors scoped under the top-level document role
    and performs the Save click as the final action.
    """
    # Desired address values
    street0 = "456 Oak Avenue"
    street1 = "Apartment 5B"
    city = "New York"
    region_label = "New York"
    postcode = "10001"

    # Scope to the top-level document per the accessibility tree guidance
    root = page.get_by_role("document", name="Magento Admin")

    # Ensure the page is settled
    await page.wait_for_load_state("networkidle")
    await page.wait_for_timeout(250)

    # --- Street Address ---
    # Primary labeled textbox (Street Address *)
    try:
        street_lbl = root.get_by_label("Street Address *")
        if await street_lbl.count():
            await street_lbl.first().fill(street0)
    except Exception:
        # ignore and continue to fallbacks
        pass

    # Fill the second street line. The accessibility tree shows the second textbox
    # is inside the same cell that contains the current street text. Locate that
    # cell and then its textboxes.
    try:
        street_cell = root.get_by_role("cell", name=street0)
        if await street_cell.count():
            tbs = street_cell.first().get_by_role("textbox")
            if await tbs.count() > 1:
                await tbs.nth(1).fill(street1)
            else:
                # fallback: try to find the row and its textboxes
                row = root.get_by_role("row").filter(has=street_cell.first())
                if await row.count():
                    row_tbs = row.first().get_by_role("textbox")
                    if await row_tbs.count() > 1:
                        await row_tbs.nth(1).fill(street1)
        else:
            # Broad fallback: find the labeled street textbox among all textboxes and fill the next textbox
            all_tbs = root.get_by_role("textbox")
            total = await all_tbs.count()
            if total:
                # Attempt to find the textbox currently containing the street0 value
                for i in range(total):
                    try:
                        val = await all_tbs.nth(i).input_value()
                    except Exception:
                        val = ""
                    if val.strip() == street0 or (street0.startswith(val.strip()) and val.strip()):
                        if i + 1 < total:
                            await all_tbs.nth(i + 1).fill(street1)
                        break
    except Exception:
        pass

    # --- City ---
    try:
        city_tb = root.get_by_role("textbox", name="City *")
        if await city_tb.count():
            await city_tb.first().fill(city)
        else:
            # alternate label variants
            for alt in ["Town/City", "Shipping City"]:
                alt_tb = root.get_by_role("textbox", name=alt)
                if await alt_tb.count():
                    await alt_tb.first().fill(city)
                    break
    except Exception:
        pass

    # --- State/Province ---
    try:
        state_cb = root.get_by_role("combobox", name="State/Province *")
        if await state_cb.count():
            # Prefer selecting by visible label
            try:
                await state_cb.first().select_option(label=region_label)
            except Exception:
                # fallback to value
                try:
                    await state_cb.first().select_option(value="NY")
                except Exception:
                    pass
        else:
            # fallback to textbox variants
            for lbl in ["Region", "State", "State/Province/Region"]:
                loc = root.get_by_role("textbox", name=lbl)
                if await loc.count():
                    await loc.first().fill(region_label)
                    break
    except Exception:
        pass

    # --- Zip/Postal Code ---
    try:
        zip_tb = root.get_by_role("textbox", name="Zip/Postal Code *")
        if await zip_tb.count():
            await zip_tb.first().fill(postcode)
        else:
            for lbl in ["ZIP/Postal Code", "Zip", "Postcode", "Postal Code"]:
                loc = root.get_by_role("textbox", name=lbl)
                if await loc.count():
                    await loc.first().fill(postcode)
                    break
    except Exception:
        pass

    # Allow client-side validation to settle
    await page.wait_for_timeout(300)

    # --- Click Save Order Address (final action) ---
    # Use the full path per guidance: scope under the document role
    save_btn = root.get_by_role("button", name="Save Order Address")
    if await save_btn.count():
        await save_btn.first().click()
        return

    # Fallbacks (scoped under document)
    for name in ["Save Address", "Save"]:
        btn = root.get_by_role("button", name=name)
        if await btn.count():
            await btn.first().click()
            return

    # Final fallback: any button containing the text 'Save'
    try:
        btns = root.get_by_role("button").filter(has_text="Save")
        if await btns.count():
            await btns.first().click()
            return
    except Exception:
        pass

    # If we couldn't find a Save control, raise so the caller knows changes were not persisted
    raise RuntimeError("Save control not found on the address edit page")

